/// Static instance of all emojis
pub static EMOJIS: LazyLock<Vec<Emoji>> = LazyLock::new(build_emojis);

/// Get all available emojis
pub fn all_emojis() -> &'static [Emoji] {
    &EMOJIS
}

/// Get an emoji by its unicode representation
pub fn emoji_from_unicode(unicode: &str) -> Option<&'static Emoji> {
    unicode::MAP.get(unicode).map(|&idx| &EMOJIS[idx])
}

/// Get an emoji by its shortcode
pub fn emoji_from_shortcode(shortcode: &str) -> Option<&'static Emoji> {
    shortcode::MAP.get(shortcode).map(|&idx| &EMOJIS[idx])
}

